import{_ as p,a0 as l,w as o,s as r,ao as u,I as a,x as i,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何为 Linux 虚拟控制台配置鼠标支持 | LCTT x X-CMD","titleTemplate":false,"description":"如何为 Linux 虚拟控制台配置鼠标支持 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何为 Linux 虚拟控制台配置鼠标支持 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何为 Linux 虚拟控制台配置鼠标支持 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180912 How To Configure Mouse Support For Linux Virtual Consoles","title":"如何为 Linux 虚拟控制台配置鼠标支持","tag":"201809","desc":""},"relativePath":"201809/20180912 How To Configure Mouse Support For Linux Virtual Consoles.md","filePath":"[post].md"}'),d={name:"201809/20180912 How To Configure Mouse Support For Linux Virtual Consoles.md"};function g(h,s,c,b,k,m){const n=l("Link");return o(),r("div",null,[s[15]||(s[15]=u(`<h1 id="如何为-linux-虚拟控制台配置鼠标支持" tabindex="-1">如何为 Linux 虚拟控制台配置鼠标支持 <a class="header-anchor" href="#如何为-linux-虚拟控制台配置鼠标支持" aria-label="Permalink to “如何为 Linux 虚拟控制台配置鼠标支持”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/GPM-1-720x340.png" alt=""></p><p>我使用 Oracle VirtualBox 来测试各种类 Unix 操作系统。我的大多数虚拟机都是<ruby>无头<rt>headless</rt></ruby>服务器，它们没有图形桌面环境。很长一段时间，我一直想知道如何在无头 Linux 服务器的基于文本的终端中使用鼠标。感谢 <strong>GPM</strong>，今天我了解到我们可以在虚拟控制台中使用鼠标进行复制和粘贴操作。 <strong>GPM</strong>，是<ruby>通用鼠标<rt>General Purpose Mouse</rt></ruby>的首字母缩写，它是一个守护程序，可以帮助你配置 Linux 虚拟控制台的鼠标支持。请不要将 GPM 与 <strong>GDM</strong>（<ruby>GNOME 显示管理器<rt>GNOME Display manager</rt></ruby>）混淆。两者有完全不同的用途。</p><p>GPM 在以下场景中特别有用：</p><ul><li>新的 Linux 服务器安装或默认情况下不能或不使用 X Windows 的系统，如 Arch Linux 和 Gentoo。</li><li>在虚拟终端/控制台中使用复制/粘贴操作。</li><li>在基于文本的编辑器和浏览器中使用复制/粘贴（例如，emacs、lynx）。</li><li>在文本文件管理器中使用复制/粘贴（例如 Ranger、Midnight commander）。</li></ul><p>在这个简短的教程中，我们将看到如何在类 Unix 操作系统中在基于文本的终端中使用鼠标。</p><h3 id="安装-gpm" tabindex="-1">安装 GPM <a class="header-anchor" href="#安装-gpm" aria-label="Permalink to “安装 GPM”">​</a></h3><p>要在纯文本 Linux 系统中启用鼠标支持，请安装 GPM 包。它在大多数 Linux 发行版的默认仓库中都有。</p><p>在 Arch Linux 及其变体如 Antergos、Manjaro Linux 上，运行以下命令来安装 GPM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S gpm</span></span></code></pre></div><p>在 Debian、Ubuntu、Linux Mint 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install gpm</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install gpm</span></span></code></pre></div><p>在 openSUSE 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install gpm</span></span></code></pre></div><p>安装后，使用以下命令启用并启动 GPM 服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable gpm</span></span>
<span class="line"><span>$ sudo systemctl start gpm</span></span></code></pre></div><p>在基于 Debian 的系统中，gpm 服务将在你安装后自动启动，因此你无需如上所示手动启动服务。</p><h3 id="为-linux-虚拟控制台配置鼠标支持" tabindex="-1">为 Linux 虚拟控制台配置鼠标支持 <a class="header-anchor" href="#为-linux-虚拟控制台配置鼠标支持" aria-label="Permalink to “为 Linux 虚拟控制台配置鼠标支持”">​</a></h3><p>无需特殊配置。GPM 将在你安装并启动 gpm 服务后立即开始工作。</p><p>在安装 GPM 之前，看下我的 Ubuntu 18.04 LTS 服务器的屏幕截图：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/Ubuntu-18.04-CLI.png" alt=""></p><p>正如你在上面的截图中看到的，我的 Ubuntu 18.04 LTS 无头服务器中没有可见的鼠标指针。只有一个闪烁的光标，它不能让我选择文本，使用鼠标复制/粘贴文本。在仅限 CLI 的 Linux 服务器中，鼠标根本没用。</p><p>在安装 GPM 后查看 Ubuntu 18.04 LTS 服务器的以下截图：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/GPM.png" alt=""></p><p>看见了吗？我现在可以选择文字了。</p><p>要选择，复制和粘贴文本，请执行以下操作：</p><ul><li>要选择文本，请按下鼠标左键并拖动鼠标。</li><li>选择文本后，放开鼠标左键，并按下中键在同一个或另一个控制台中粘贴文本。</li><li>右键用于扩展选择，就像在 <code>xterm</code> 中。</li><li>如果你使用的是双键鼠标，请使用右键粘贴文本。</li></ul><p>就这么简单！</p><p>就像我已经说过的那样，GPM 工作得很好，并且不需要额外的配置。以下是 GPM 配置文件 <code>/etc/gpm.conf</code>（或在某些发行版中是 <code>/etc/conf.d/gpm</code>）的示例内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># protected from evaluation (i.e. by quoting them).</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span># This file is used by /etc/init.d/gpm and can be modified by</span></span>
<span class="line"><span># &quot;dpkg-reconfigure gpm&quot; or by hand at your option.</span></span>
<span class="line"><span>#</span></span>
<span class="line"><span>device=/dev/input/mice</span></span>
<span class="line"><span>responsiveness=</span></span>
<span class="line"><span>repeat_type=none</span></span>
<span class="line"><span>type=exps2</span></span>
<span class="line"><span>append=&#39;&#39;</span></span>
<span class="line"><span>sample_rate=</span></span></code></pre></div><p>在我的例子中，我使用 USB 鼠标。如果你使用的是其他鼠标，则可能需要更改 <code>device=/dev/input/mice</code> 和 <code>type=exps2</code> 参数的值。</p><p>有关更多详细信息，请参阅手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man gpm</span></span></code></pre></div><p>就是这些了。希望这个有用。还有更多的好东西。敬请期待！</p><p>干杯!</p><hr>`,38)),a("p",null,[s[1]||(s[1]=i("via: ",-1)),e(n,{href:"https://www.ostechnix.com/how-to-configure-mouse-support-for-linux-virtual-consoles/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-configure-mouse-support-for-linux-virtual-consoles/",-1)])]),_:1})]),a("p",null,[s[6]||(s[6]=i("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" \u2028选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" \u2028译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" \u2028校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[12]||(s[12]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const C=p(d,[["render",g]]);export{y as __pageData,C as default};
